ST.xhtml:p:
FBZAxisTouchPanel();
FBZAixsAbs();
(*IF g_nFAxisControlType=3 THENFBZAxisPresterCal();*)
IF g_nCalibrationType = 0 THEN(*电容标定*)
  FBZAxisCal();
  g_ZAxisRealTimeCalibrate.ENABLE := FALSE;
ELSIF g_nCalibrationType = 1 THEN (*NC标定*)
  FBZAxisNCCalControl();
  FBZAxisSelfTuning();
  FBZAxisRealTimeCalibrate();
END_IF;
IF g_nCalibrationType = 0 THEN
  g_ZAxisRealTimeCalibrate.ENABLE := FALSE;
END_IF;
FBZAxisActMotion();
FBZAxisHome();
FBZAxisJog();
FBZAxisRel();
FBZAxisPower();
FBZAxisOverride();
FBZAxisLeapFrog();
FBZAxisFollow();
FBZAxisLift();
FBZAxisTorqueMonitor();
FBCycleZRelMove();
AutoZChangeFollowKP();
FBZAxisFollowSmooth();
FBZAxisCoordCutFrog();
(*标定碰板时或HMI获取Z轴当前坐标，用于坐标切割模式坐标计算*)
RTrigge(CLK := g_bReadZAxisPosfbDown);
IF RTrigge.Q THEN
  g_fZAxisPosfbDown := Axis_Z.NCTOPLC.ACTPOS;  (*Z轴定位坐标*)
  ZPosfbToSave(ENABLE := TRUE); (*Z轴碰板坐标保存*)
  g_bReadZAxisPosfbDown := FALSE;
END_IF;

(*IF g_bManualRTCPUseCompen AND g_bABAxisIsConfig THEN
  CNCZAxisVelAdd();
END_IF;*)

IF g_bABAxisIsConfig THEN
  IF g_bManualRTCPUseCompen THEN (*手动模式下*)
    CNCZAxisVelAdd();
  ELSIF g_nMotionMode = 2 AND  g_bUseNewVelAddModule  THEN(*自动模式下*)
    CNCZAxisVelAdd();
  END_IF; 
ELSE
  IF g_bUseNewVelAddModule THEN(*自动模式下*)
    CNCZAxisVelAdd();
  END_IF; 
END_IF;
g_fLastCoord := g_fiZFollowCoord;


R_Trigger(CLK := g_bplcHardwareResetBuffer OR (g_bClearAlarmButtonClickedBuffer AND g_dCurPlcState <> 1.0 AND  Axis_Z.NCTOPLC.AXISSTATE = 3 ));

IF R_Trigger.Q THEN
  g_ZReset.Execute := FALSE;
  nClearState := 3;
END_IF;

CASE nClearState OF
  0:
    nClearState := 0;
  3: 
    IF Axis_Z.NCTOPLC.AXISSTATE = 3 THEN  (*Z轴错误状态直接复位*)
      nClearState := 15;
    ELSE
      nClearState := 5;  (*Z轴非错误状态，先暂停后复位*)
    END_IF;   
  5:  
    IF Axis_Z.NCTOPLC.AxisState = 9 THEN
      nClearState := 7;
    ELSE
      nClearState := 10;
    END_IF;
  7:
    g_bZFollowClose := TRUE;
    nClearState := 8;
  8:
    g_nFollowState :=170;
    IF g_bZFollowOutDone THEN      
      nClearState := 10;
    END_IF;  
  10:
    IF Axis_Z.NCTOPLC.AXISSTATE <> 1 THEN (*未上使能*)
      g_ZMoveStop.Execute := TRUE;
      IF g_ZMoveStop.Done THEN
        g_ZMoveStop.Execute := FALSE;
        IF g_nFollowMode = 0 THEN (*Z轴随动模式：0速度模式 1位置模式,解决EDS2000会有跟随误差，复位轴会移动*)
          nClearState := 15;
        ELSE
          nClearState := 0;
        END_IF;
      END_IF;
      IF g_ZMoveStop.CommandAborted OR g_ZMoveStop.Error THEN
        g_ZMoveStop.Execute := FALSE;
        nClearState := 0;
      END_IF; 
    ELSE
      nClearState := 15; 
    END_IF; 
  15:
    g_ZReset.Execute := TRUE;
    IF g_ZReset.DONE OR g_ZReset.ERROR THEN
      g_ZReset.Execute := FALSE;
      nClearState := 0;
    END_IF;

END_CASE;
